  insert into public.marketing_permission_records (id, job_type, job_id, source, decision, supersedes_id, grantor_name, grantor_capacity, method, evidence_summary, note, recorded_by, recorded_at) values ('00000000-0000-4000-8000-0000000f3005','crew_support_request','00000000-0000-4000-8000-0000000f1031','admin_recorded','withdrawn','00000000-0000-4000-8000-0000000f3004','Synthetic Client','client','message','client withdrew by message thread','client withdrew','00000000-0000-4000-8000-0000000f0001', now() - interval '7 years');
  insert into public.portfolio_use_events (project_file_id, destination, action, actor_id, occurred_at) values ('00000000-0000-4000-8000-0000000f1034','website','published','00000000-0000-4000-8000-0000000f0001', now() - interval '3 years'),('00000000-0000-4000-8000-0000000f1034','website','ended','00000000-0000-4000-8000-0000000f0001', now() - interval '2 years');
