set session_replication_role = origin;

do $$
declare J1 uuid := '00000000-0000-4000-8000-0000000f1011'; FL1 uuid := '00000000-0000-4000-8000-0000000f1014'; G1 uuid := '00000000-0000-4000-8000-0000000f3001'; G2 uuid := '00000000-0000-4000-8000-0000000f3002'; G4 uuid := '00000000-0000-4000-8000-0000000f3006'; G3 uuid := '00000000-0000-4000-8000-0000000f3004';
  FOUNDER uuid := '00000000-0000-4000-8000-0000000f0001'; STAFF uuid := '00000000-0000-4000-8000-0000000f0002'; s1 record; s2 record; r record; c record; ok boolean;
  procedure_note text;
begin
  -- 1. an in-force grant is never erased, on any basis
  begin perform public.marketing_permission_record_redact(G1, FOUNDER, 'retention period ended for this record', 'data_subject_request', true); raise exception 'FAIL erased in force'; exception when others then if sqlerrm like 'FAIL%' then raise; end if; end; raise notice 'PASS 1 an in-force permission cannot be erased';
  insert into public.marketing_permission_records (job_type, job_id, source, decision, supersedes_id, grantor_name, grantor_capacity, method, evidence_summary, note, recorded_by)
    values ('crew_support_request',J1,'admin_recorded','withdrawn',G1,'Synthetic Client','client','message','client withdrew by message thread','client withdrew',FOUNDER);
  select * into s1 from public.marketing_permission_state(FL1, 'website');
  -- 2. validation
  begin perform public.marketing_permission_record_redact(G1, FOUNDER, 'retention period ended for this record', 'data_subject_request', false); raise exception 'FAIL no confirmation'; exception when others then if sqlerrm like 'FAIL%' then raise; end if; end; raise notice 'PASS 2a confirmation required';
  begin perform public.marketing_permission_record_redact(G1, STAFF, 'retention period ended for this record', 'data_subject_request', true); raise exception 'FAIL staff'; exception when others then if sqlerrm like 'FAIL%' then raise; end if; end; raise notice 'PASS 2b management only';
  begin perform public.marketing_permission_record_redact(G1, FOUNDER, 'short', 'data_subject_request', true); raise exception 'FAIL short reason'; exception when others then if sqlerrm like 'FAIL%' then raise; end if; end; raise notice 'PASS 2c a reason is required';
  begin perform public.marketing_permission_record_redact(G1, FOUNDER, 'retention period ended for this record', 'because', true); raise exception 'FAIL bad basis'; exception when others then if sqlerrm like 'FAIL%' then raise; end if; end; raise notice 'PASS 2d the basis must be one of the recorded bases';
  -- 3. retention basis: no policy recorded -> refused; staff cannot record a policy; management records it; recent withdrawal -> period not ended
  select * into c from public.marketing_permission_record_erasure_check(G1, 'retention_period_ended'); assert c.blockers::text like '%no retention policy%', 'no policy must block the retention basis';
  begin perform public.marketing_permission_record_redact(G1, FOUNDER, 'retention period ended for this record', 'retention_period_ended', true); raise exception 'FAIL retention basis without policy'; exception when others then if sqlerrm like 'FAIL%' then raise; end if; end; raise notice 'PASS 3a no policy recorded: the retention basis is refused (nothing is seeded)';
  begin insert into public.portfolio_retention_policy (retention_years, policy_note, adopted_by) values (6,'six years after the permission and last use ended; longer only where a duty, dispute or hold requires',STAFF); raise exception 'FAIL staff recorded policy'; exception when others then if sqlerrm like 'FAIL%' then raise; end if; end; raise notice 'PASS 3b only management may record the policy';
  insert into public.portfolio_retention_policy (retention_years, policy_note, adopted_by) values (6,'six years after the permission and last use ended; longer only where a duty, dispute or hold requires',FOUNDER);
  begin update public.portfolio_retention_policy set retention_years = 1; raise exception 'FAIL policy edited'; exception when others then if sqlerrm like 'FAIL%' then raise; end if; end; raise notice 'PASS 3c the policy record is append-only';
  select * into c from public.marketing_permission_record_erasure_check(G1, 'retention_period_ended'); assert c.blockers::text like '%retention period has not ended%' and c.earliest_retention_date > current_date + interval '5 years', 'recent end: period not ended';
  begin perform public.marketing_permission_record_redact(G1, FOUNDER, 'retention period ended for this record', 'retention_period_ended', true); raise exception 'FAIL erased before the period ended'; exception when others then if sqlerrm like 'FAIL%' then raise; end if; end; raise notice 'PASS 3d erasure on the retention basis is refused until six years after the permission and last use ended';
  -- 4. older records: end 7 years ago, last use ended 7y1m ago -> allowed; end 7 years ago but last use only 2 years ago -> blocked until use+6y
  select * into c from public.marketing_permission_record_erasure_check(G2, 'retention_period_ended'); assert coalesce(array_length(c.blockers, 1), 0) = 0, 'old record should be erasable: ' || c.blockers::text;
  select * into c from public.marketing_permission_record_erasure_check(G3, 'retention_period_ended'); assert c.blockers::text like '%retention period has not ended%', 'a recent use delays the period';
  raise notice 'PASS 4 the period runs from the later of the permission end and the last use';
  select * into c from public.marketing_permission_record_erasure_check(G4, 'retention_period_ended'); assert c.blockers::text like '%stored evidence file reference exists%' and array_length(c.blockers,1) = 1, 'the stored file is the only blocker on G4: ' || c.blockers::text;
  -- 5. other bases skip the period but not the safeguards; a stored file must be removed first; holds; in use
  begin perform public.marketing_permission_record_redact(G4, FOUNDER, 'six year retention period ended for this record', 'retention_period_ended', true); raise exception 'FAIL erased a record with a stored file'; exception when others then if sqlerrm like 'FAIL%' then raise; end if; end; raise notice 'PASS 5a a record that references a stored evidence file can never be erased (no override)';
  insert into public.marketing_permission_job_holds (job_type, job_id, action, reason, recorded_by) values ('crew_support_request',J1,'placed','complaint under review: keep all evidence',FOUNDER);
  begin perform public.marketing_permission_record_redact(G1, FOUNDER, 'data subject asked for erasure of details', 'data_subject_request', true); raise exception 'FAIL erased under job hold'; exception when others then if sqlerrm like 'FAIL%' then raise; end if; end; raise notice 'PASS 5b a job hold blocks every basis';
  begin insert into public.marketing_permission_job_holds (job_type, job_id, action, reason, recorded_by) values ('crew_support_request',J1,'released','complaint closed, no further action',STAFF); raise exception 'FAIL staff released'; exception when others then if sqlerrm like 'FAIL%' then raise; end if; end; raise notice 'PASS 5c only management may place or release a hold';
  begin update public.marketing_permission_job_holds set reason = 'edited reason of the hold' where job_id = J1; raise exception 'FAIL hold edited'; exception when others then if sqlerrm like 'FAIL%' then raise; end if; end;
  insert into public.marketing_permission_job_holds (job_type, job_id, action, reason, recorded_by) values ('crew_support_request',J1,'released','complaint closed, no further action',FOUNDER);
  insert into public.portfolio_file_holds (project_file_id, action, reason, recorded_by) values (FL1,'placed','audit requires the photograph evidence kept',FOUNDER);
  begin perform public.marketing_permission_record_redact(G1, FOUNDER, 'data subject asked for erasure of details', 'data_subject_request', true); raise exception 'FAIL erased under file hold'; exception when others then if sqlerrm like 'FAIL%' then raise; end if; end; raise notice 'PASS 5d a photograph-level hold also blocks';
  insert into public.portfolio_file_holds (project_file_id, action, reason, recorded_by) values (FL1,'released','audit closed, evidence no longer needed',FOUNDER);
  set local session_replication_role = replica; insert into public.portfolio_use_events (project_file_id, destination, action, actor_id) values (FL1,'website','published',FOUNDER); set local session_replication_role = origin;
  begin perform public.marketing_permission_record_redact(G1, FOUNDER, 'data subject asked for erasure of details', 'data_subject_request', true); raise exception 'FAIL erased while in use'; exception when others then if sqlerrm like 'FAIL%' then raise; end if; end; raise notice 'PASS 5e refused while a photograph of the job is still in use for a covered use';
  set local session_replication_role = replica; insert into public.portfolio_use_events (project_file_id, destination, action, actor_id) values (FL1,'website','ended',FOUNDER); set local session_replication_role = origin;
  -- 5f. fail closed: the same record stays refused on every basis even with confirmation, so no reference can be dropped while a file may remain
  begin perform public.marketing_permission_record_redact(G4, FOUNDER, 'legal requirement to erase the details', 'legal_requirement', true); raise exception 'FAIL erased with stored file on legal basis'; exception when others then if sqlerrm like 'FAIL%' then raise; end if; end; raise notice 'PASS 5f the stored-file rule fails closed on every basis';
  -- 6. erasure on the data-subject-request basis (shorter retention where required): details gone, structure kept, state unchanged, logged with basis
  perform public.marketing_permission_record_redact(G1, FOUNDER, 'data subject asked for erasure of details', 'data_subject_request', true);
  select * into r from public.marketing_permission_records where id = G1;
  assert r.grantor_name = '[erased]' and r.evidence_summary like '[erased%' and r.note like '[erased%' and r.evidence_storage_path is null, 'personal fields erased';
  assert r.decision = 'granted' and r.allowed_destinations = array['website'] and r.verification_status = 'verified' and r.source = 'admin_recorded' and r.job_id = J1, 'decision structure kept';
  assert exists (select 1 from public.marketing_permission_records where supersedes_id = G1 and grantor_name = '[erased]'), 'withdrawal row erased with its grant';
  select * into s2 from public.marketing_permission_state(FL1, 'website'); assert s2.effective is not distinct from s1.effective and s2.reason is not distinct from s1.reason, 'eligibility result must not change';
  assert (select count(*) from public.marketing_permission_redactions where record_id = G1 and basis = 'data_subject_request' and confirmed_permitted) = 1, 'logged with basis'; raise notice 'PASS 6 erasure keeps the decision structure, leaves the permission state unchanged and logs the basis';
  -- 7. an old record on the retention basis is erased once the period has ended
  perform public.marketing_permission_record_redact(G2, FOUNDER, 'six year retention period ended for this record', 'retention_period_ended', true);
  assert (select grantor_name from public.marketing_permission_records where id = G2) = '[erased]', 'old record erased'; raise notice 'PASS 7 the retention basis works once six years have passed since the end and the last use';
  -- 8. immutability, log append-only, privileges
  begin update public.marketing_permission_records set allowed_destinations = array['portfolio'] where id = G1; raise exception 'FAIL edited outside erasure'; exception when others then if sqlerrm like 'FAIL%' then raise; end if; end;
  begin delete from public.marketing_permission_records where id = G1; raise exception 'FAIL delete allowed'; exception when others then if sqlerrm like 'FAIL%' then raise; end if; end; raise notice 'PASS 8a rows remain immutable and undeletable outside erasure';
  begin update public.marketing_permission_redactions set reason = 'edited reason for the log' where record_id = G1; raise exception 'FAIL log edited'; exception when others then if sqlerrm like 'FAIL%' then raise; end if; end; raise notice 'PASS 8b the erasure log is append-only';
  assert (select count(*) from information_schema.role_table_grants where table_name in ('marketing_permission_job_holds','marketing_permission_redactions','portfolio_retention_policy') and grantee in ('anon','authenticated','PUBLIC')) = 0, 'client grants';
  assert (select count(*) from information_schema.role_table_grants where table_name in ('marketing_permission_job_holds','marketing_permission_redactions','portfolio_retention_policy') and grantee='service_role' and privilege_type in ('DELETE','TRUNCATE','UPDATE','REFERENCES','TRIGGER','MAINTAIN')) = 0, 'dangerous grants';
  assert (select count(*) from pg_class where relname in ('marketing_permission_job_holds','marketing_permission_redactions','portfolio_retention_policy') and relrowsecurity) = 3, 'rls';
  assert (select count(*) from pg_proc p where p.proname in ('marketing_permission_record_redact','marketing_permission_record_erasure_check') and (has_function_privilege('anon', p.oid,'execute') or has_function_privilege('authenticated', p.oid,'execute'))) = 0, 'client exec'; raise notice 'PASS 8c RLS on, no client access, no update/delete for the service role, functions server-only';
  insert into public.marketing_permission_records (job_type, job_id, source, decision, grantor_name, grantor_capacity, allowed_destinations, method, evidence_summary, verification_status, recorded_by)
    values ('crew_support_request',J1,'admin_recorded','granted','Synthetic Client','client',array['website'],'message','a fresh message thread confirming use','verified',FOUNDER);
  select * into s2 from public.marketing_permission_state(FL1, 'website'); assert s2.effective is true, 'a new verified grant works'; raise notice 'PASS 9 later grants are evaluated normally';
end $$;
rollback;
